Here is a Python solution using the QuickSelect algorithm, which is an in-place variation of the QuickSort algorithm. This algorithm has an average time complexity of O(n) and a worst-case time complexity of O(n^2), but it performs well on average and is efficient for large arrays.

```python
def quickselect_median(l, pivot_fn):
    if len(l) % 2 == 1:
        return quickselect(l, len(l) // 2, pivot_fn)
    else:
        return 0.5 * (quickselect(l, len(l) // 2 - 1, pivot_fn) +
                      quickselect(l, len(l) // 2, pivot_fn))


def quickselect(l, k, pivot_fn):
    if len(l) == 1:
        assert k == 0
        return l[0]

    pivot = pivot_fn(l)

    lows = [el for el in l if el < pivot]
    highs = [el for el in l if el > pivot]
    pivots = [el for el in l if el == pivot]

    if k < len(lows):
        return quickselect(lows, k, pivot_fn)
    elif k < len(lows) + len(pivots):
        return pivots[0]
    else:
        return quickselect(highs, k - len(lows) - len(pivots), pivot_fn)


def pivot_fn(l):
    n = len(l)
    assert n > 0

    if n < 5:
        return median_of_medians(l)

    chunks = chunked(l, 5)
    full_chunks = [chunk for chunk in chunks if len(chunk) == 5]
    sorted_groups = [sorted(chunk) for chunk in full_chunks]
    medians = [chunk[2] for chunk in sorted_groups]

    return quickselect(medians, len(medians) // 2, pivot_fn)


def chunked(l, chunk_size):
    return [l[i:i + chunk_size] for i in range(0, len(l), chunk_size)]


def median_of_medians(l):
    assert len(l) > 0

    if len(l) < 5:
        return sorted(l)[len(l) // 2]

    chunks = chunked(l, 5)
    medians = [chunk[len(chunk) // 2] for chunk in chunks]

    return median_of_medians(medians)


def validate_input(l):
    if not isinstance(l, list):
        raise TypeError("Input should be a list")
    if not all(isinstance(i, (int, float)) for i in l):
        raise ValueError("All elements in the list should be numeric")


def find_median(l):
    validate_input(l)
    if len(l) == 0:
        raise ValueError("List is empty")
    if len(l) == 1:
        return l[0]
    return quickselect_median(l, pivot_fn)
