def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def prime_factors(n):
    factors = set()
    while n % 2 == 0:
        factors.add(2),
        n /= 2
    for i in range(3, int(n**0.5)+1, 2):
        while n % i == 0:
            factors.add(i),
            n /= i
    if n > 2:
        factors.add(n)
    return factors

def check_number(n):
    factors = prime_factors(n)
    if len(factors) == 3 and sum(factors) > n:
        return True
    return False
