Here is a Python solution that uses the Sieve of Eratosthenes algorithm to generate all prime numbers up to 1,000,000, and then uses binary search to find the first prime number greater than 1,000,000 in the given array.

```python
import math

def sieve_of_eratosthenes(n):
    primes = [True for i in range(n+1)]
    p = 2
    while (p * p <= n):
        if (primes[p] == True):
            for i in range(p * p, n+1, p):
                primes[i] = False
        p += 1
    prime_numbers = [p for p in range(2, n) if primes[p]]
    return prime_numbers

def binary_search(arr, x):
    low = 0
    high = len(arr) - 1
    mid = 0
    while low <= high:
        mid = (high + low) // 2
        if arr[mid] < x:
            low = mid + 1
        elif arr[mid] > x:
            high = mid - 1
        else:
            return mid
    return -1

def find_first_prime(arr):
    if not arr:
        return -1
    primes = sieve_of_eratosthenes(10**7)
    for num in arr:
        if num > 10**6 and binary_search(primes, num) != -1:
            return arr.index(num)
    return -1
```

