    if b == 0:
        return a
    if ~(a | b) & 1:
        return a >> 1 << 1 if ~(a ^ b) & 1 else highest_common_factor(a >> 1, b >> 1) << 1
    if ~a & 1:
        return highest_common_factor(a >> 1, b)
    if ~b & 1:
