def remove_symbols(s):
    stack = []
    vowels = set('aeiouAEIOU')
    vowel_count = 0
    for c in s:
        if c.isalpha():
            if c.islower():
                stack.append(c)
                if c in vowels:
                    vowel_count += 1
            elif stack and stack[-1].isupper():
                stack.append(c)
                if c in vowels:
                    vowel_count += 1
            elif not stack or stack[-1].islower():
                stack.append(c)
                if c in vowels:
                    vowel_count += 1
    return ''.join(stack), vowel_count

def solve(s):
