def merge_sort(my_list, descending=False):
    if len(my_list) <= 1:
        return my_list

    mid = len(my_list) // 2
    left_half = my_list[:mid]
    right_half = my_list[mid:]

    return merge(merge_sort(left_half, descending), merge_sort(right_half, descending), descending)

def merge(left, right, descending):
    merged = []
    left_index = 0
    right_index = 0

    while left_index < len(left) and right_index < len(right):
        if descending:
            if left[left_index].name > right[right_index].name or (left[left_index].name == right[right_index].name and left[left_index].age > right[right_index].age):
                merged.append(left[left_index])
                left_index += 1
            else:
                merged.append(right[right_index])
                right_index += 1
        else:
            if left[left_index].name < right[right_index].name or (left[left_index].name == right[right_index].name and left[left_index].age < right[right_index].age):
                merged.append(left[left_index])
                left_index += 1
            else:
                merged.append(right[right_index])
                right_index += 1

    merged.extend(left[left_index:])
    merged.extend(right[right_index:])
    return merged

