import random
from math import sqrt

def is_prime(n):
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    max_div = round(sqrt(n))
    for i in range(3, 1 + max_div, 2):
        if n % i == 0:
            return False
    return True

def find_difference(num1, num2):
    if not is_prime(num1) or not is_prime(num2):
        raise ValueError("Both numbers must be prime")
    if num1 < -1000 or num1 > 1000 or num2 < -1000 or num2 > 1000:
        raise ValueError("Numbers must be within the range of -1000 to 1000")
    prime_numbers = [i for i in range(1, 101) if is_prime(i)]
    random_prime = random.choice(prime_numbers)
    difference = abs(num1 - num2)
    if difference % random_prime != 0:
        raise ValueError("The difference is not divisible by the random prime number")
    return difference
```

