def fibonacci(n, cache):
    MOD = 10**9 + 7
    if n in cache:
        return cache[n]
    elif n < 0:
        return -fibonacci(-n, cache)
    else:
        if n == 0 or n == 1:
            return n
        else:
            cache[n] = (fibonacci(n-1, cache) + fibonacci(n-2, cache)) % MOD
            return cache[n]
```

