from collections import Counter

def common_elements(*arrays):
    # Validate input
    for array in arrays:
        if not isinstance(array, list) or not all(isinstance(i, int) for i in array):
            raise ValueError("All inputs must be lists of integers.")

    # Count elements in all arrays
    counter = Counter()
    for array in arrays:
        counter.update(array)

    # Find common elements
    common = {k: v for k, v in counter.items() if v == len(arrays)}

    return common

# Test cases
