        seconds %= 3600
    else:
        hours = 0

    if seconds >= 60:
        minutes = seconds // 60
        seconds %= 60
    else:
        minutes = 0

    return f"{years} years, {months} months, {weeks} weeks, {days} days, {hours} hours, {minutes} minutes, {seconds} seconds"

