import re
from datetime import datetime

class Person:
    def __init__(self, name, age, hobbies, address):
        self.name = name
        self.age = age
        self.hobbies = hobbies
        self.address = address

    @property
    def age(self):
        return self._age

    @age.setter
    def age(self, value):
        if not isinstance(value, int) or value < 0:
            raise ValueError("Age must be a positive integer")
        self._age = value

    @property
    def zip_code(self):
        return self.address['zip_code']

    @zip_code.setter
    def zip_code(self, value):
        if not re.match(r'^\d{5}$', value):
            raise ValueError("Zip code must be a 5-digit number")
        self.address['zip_code'] = value

    def age_in_months(self):
        current_year = datetime.now().year
        current_month = datetime.now().month
        age_in_months = (current_year - 1900) * 12 + current_month - self.age * 12
        return age_in_months

    def birth_year(self):
        current_year = datetime.now().year
        birth_year = current_year - self.age
        return birth_year

    def add_hobby(self, hobby):
        if len(self.hobbies) >= 5:
            raise ValueError("Maximum number of hobbies reached")
        self.hobbies.append(hobby)

    def remove_hobby(self, hobby):
        if hobby in self.hobbies:
            self.hobbies.remove(hobby)

    def search_hobby(self, hobby):
        for h in self.hobbies:
            if hobby.lower() in h.lower():
                return True
        return False

    def full_address(self):
        return f"{self.address['house_number']} {self.address['street_name']}, {self.address['city']}, {self.address['state']} {self.address['zip_code']}"

    def display_data(self):
        print(f"Name: {self.name.title()}")
        print(f"Age: {self.age}")
        print(f"Hobbies: {', '.join(self.hobbies)}")
        print(f"Address: {self.full_address()}")

    def add_address(self, address):
        if len(self.address) >= 5:
            raise ValueError("Maximum number of addresses reached")
        self.address.append(address)

    def remove_address(self, address_id):
        for address in self.address:
            if address['id'] == address_id:
                self.address.remove(address)
                return
        raise ValueError("Address not found")

    def get_address(self, address_id):
        for address in self.address:
            if address['id'] == address_id:
                return address
        raise ValueError("Address not found")
```

