```python
def binary_search(arr, val, start, end):
    if start == end:
        if arr[start] > val:
            return start
        else:
            return start + 1
    elif start > end:
        return start

    mid = (start + end) // 2
    if arr[mid] < val:
        return binary_search(arr, val, mid + 1, end)
    elif arr[mid] > val:
        return binary_search(arr, val, start, mid - 1)
    else:
        return mid

def merge(left, right):
    if not left:
        return right
    if not right:
        return left

    result = []
    left_index = 0
    right_index = 0

    while left_index < len(left) and right_index < len(right):
        if left[left_index] <= right[right_index]:
            pos = binary_search(right, left[left_index], 0, len(right) - 1)
            result.insert(pos, left[left_index])
            left_index += 1
        else:
            pos = binary_search(left, right[right_index], 0, len(left) - 1)
            result.insert(pos, right[right_index])
            right_index += 1

    while left_index < len(left):
        pos = binary_search(right, left[left_index], 0, len(right) - 1)
        result.insert(pos, left[left_index])
        left_index += 1

    while right_index < len(right):
        pos = binary_search(left, right[right_index], 0, len(left) - 1)
        result.insert(pos, right[right_index])
        right_index += 1

    return result

def merge_sort(arr):
    if len(arr) <= 1:
        return arr

    mid = len(arr) // 2
    left = merge_sort(arr[:mid])
    right = merge_sort(arr[mid:])

    return merge(left, right)
```

