```python
class Student:
    def __init__(self, name, major, age, GPA):
        self.name = name
        self.major = major
        self.age = age
        self.GPA = GPA

def group_students(student_list):
    if not isinstance(student_list, list):
        raise ValueError("Input should be a list of student objects")

    grouped_students = {}
    for student in student_list:
        if not isinstance(student, Student):
            raise ValueError("All elements in the list should be student objects")
        if student.GPA >= 3.0:
            if student.major in grouped_students:
                grouped_students[student.major].append(student.name)
            else:
                grouped_students[student.major] = [student.name]

    for major in grouped_students:
        grouped_students[major].sort()

    return grouped_students

# Unit tests
def test_group_students():
    # Test with a list of students
    students = [Student("John", "CS", 20, 3.5), Student("Jane", "CS", 22, 3.2), Student("Bob", "Math", 21, 3.7)]
    assert group_students(students) == {"CS": ["Jane", "John"], "Math": ["Bob"]}

    # Test with a list of students where some GPAs are below 3.0
    students = [Student("John", "CS", 20, 2.5), Student("Jane", "CS", 22, 3.2), Student("Bob", "Math", 21, 3.7)]
    assert group_students(students) == {"CS": ["Jane"], "Math": ["Bob"]}

    # Test with an empty list
    assert group_students([]) == {}

    # Test with a list of students where all GPAs are below 3.0
    students = [Student("John", "CS", 20, 2.5), Student("Jane", "Math", 22, 2.2), Student("Bob", "Eng", 21, 2.7)]
    assert group_students(students) == {}

    # Test with a list of students where some do not have a name
    students = [Student("John", "CS", 20, 3.5), Student(None, "CS", 22, 3.2), Student("Bob", "Math", 21, 3.7)]
    assert group_students(students) == {"CS": ["John"], "Math": ["Bob"]}

test_group_students()
```

