import datetime

class LivingBeing:
    def __init__(self, name, species):
        self.name = name
        self.species = species

class Animal(LivingBeing):
    species_lifespan = {"dog": 10, "cat": 15, "bird": 3, "fish": 5}
    species_food = {"dog": ["meat"], "cat": ["meat", "fish"], "bird": ["seeds"], "fish": ["plankton"]}
    species_sound = {"dog": "woof", "cat": "meow", "bird": "tweet", "fish": "glug"}
    species_movement = {"dog": "run", "cat": "sprint", "bird": "fly", "fish": "swim"}

    def __init__(self, name, species, creation_date):
        super().__init__(name, species)
        self.creation_date = creation_date

    @property
    def age(self):
        return (datetime.datetime.now() - self.creation_date).days

    def eat(self, food):
        if food not in self.species_food[self.species]:
            raise ValueError(f"{food} is not valid for {self.species}")
        self.age -= 1  # assuming every food item reduces the animal's age by 1 day

    @staticmethod
    def compare_age(animal1, animal2):
        return animal1.age > animal2.age

    @classmethod
    def get_average_lifespan(cls, species):
        return cls.species_lifespan[species]

    def reproduce(self):
        return type(self)(self.name, self.species, datetime.datetime.now())

    def speak(self):
        print(self.species_sound[self.species])

    def move(self):
        print(f"The {self.species} is {self.species_movement[self.species]}ing")

class Mammal(Animal):
    def __init__(self, name, species, creation_date, fur_color):
        super().__init__(name, species, creation_date)
        self.fur_color = fur_color

    def milk(self):
        print(f"The {self.species} is producing milk")

class Bird(Animal):
    def __init__(self, name, species, creation_date, wing_span):
        super().__init__(name, species, creation_date)
        self.wing_span = wing_span

    def fly(self):
        print(f"The {self.species} is flying")

class Fish(Animal):
    def __init__(self, name, species, creation_date, water_type):
        super().__init__(name, species, creation_date)
        self.water_type = water_type

    def swim(self):
        print(f"The {self.species} is swimming")
