def sieve_of_eratosthenes(limit):
    sieve = [True] * limit
    sieve[0] = sieve[1] = False

    for i, is_prime in enumerate(sieve):
        if is_prime:
            yield i
            for n in range(i*i, limit, i):
                sieve[n] = False

count = 0
for prime in sieve_of_eratosthenes(100000):
    if count < 1000:
        print(prime)
        count += 1
    else:
        break
```

