```python
import csv
import io
from django.http import HttpRequest, FileResponse

def task_func(request: HttpRequest, header: list, csv_data: list) -> FileResponse:
    # Validate the input header and csv_data
    if not isinstance(header, list) or not all(isinstance(i, str) for i in header):
        return HttpResponseBadRequest("Invalid header. It should be a list of strings.")
    if not isinstance(csv_data, list) or not all(isinstance(i, list) for i in csv_data):
        return HttpResponseBadRequest("Invalid csv_data. It should be a list of lists.")

    # Create a CSV file in memory
    output = io.StringIO()
    writer = csv.writer(output, quoting=csv.QUOTE_ALL)

    try:
        # Write the header and data to the CSV file
        writer.writerow(header)
        for row in csv_data:
            writer.writerow(row)
    except csv.Error as e:
        return HttpResponseServerError(f"Error writing CSV data: {str(e)}")

    # Reset the file pointer to the beginning
    output.seek(0)

    # Create a Django FileResponse with the CSV data
    response = FileResponse(output, content_type='text/csv')
    response['Content-Disposition'] = 'attachment; filename="output.csv"'

    return response
```

