```python
import aioredis

class AsyncKeyValueStore:
    def __init__(self, host, port, db, password):
        self.host = host
        self.port = port
        self.db = db
        self.password = password
        self.redis = None

    async def connect(self):
        try:
            self.redis = await aioredis.create_redis_pool((self.host, self.port), db=self.db, password=self.password)
        except aioredis.RedisError as e:
            print(f"Redis connection error: {e}")

    async def set_key(self, key, value, expire=None):
        try:
            if expire:
                await self.redis.set(key, value, expire=expire)
            else:
                await self.redis.set(key, value)
        except aioredis.RedisError as e:
            print(f"Redis set operation error: {e}")

    async def get_key(self, key):
        try:
            value = await self.redis.get(key)
            return value
        except aioredis.RedisError as e:
            print(f"Redis get operation error: {e}")

    async def delete_key(self, key):
        try:
            await self.redis.delete(key)
        except aioredis.RedisError as e:
            print(f"Redis delete operation error: {e}")
```

