```python
import ast
import sympy
import math
import operator as op
from collections import defaultdict

class Runtime:
    def __init__(self):
        self.variables = defaultdict(float)
        self.functions = {}
        self.builtin_functions = {
            'sin': math.sin,
            'cos': math.cos,
            'tan': math.tan,
            'asin': math.asin,
            'acos': math.acos,
            'atan': math.atan,
        }

    def execute(self, statement):
        try:
            node = ast.parse(statement, mode='eval')
            codeobj = compile(node, '<string>', mode='eval')
            if isinstance(node.body, ast.Name):
                return self.variables[statement]
            elif isinstance(node.body, ast.BinOp):
                return self._eval(node.body)
            elif isinstance(node.body, ast.Call):
                return self._eval(node.body)
            else:
                raise ValueError('Invalid statement')
        except Exception as e:
            print(f'Error: {e}')

    def _eval(self, node):
        if isinstance(node, ast.Num):
            return node.n
        elif isinstance(node, ast.BinOp):
            left = self._eval(node.left)
            right = self._eval(node.right)
            return self._operate(node.op, left, right)
        elif isinstance(node, ast.Name):
            return self.variables[node.id]
        elif isinstance(node, ast.Call):
            func_name = node.func.id
            if func_name in self.builtin_functions:
                return self.builtin_functions[func_name](self._eval(node.args[0]))
            elif func_name in self.functions:
                return self._eval(self.functions[func_name])
            else:
                raise ValueError(f'Undefined function {func_name}')
        else:
            raise ValueError('Invalid node')

    def _operate(self, op, left, right):
        operations = {
            ast.Add: op.add,
            ast.Sub: op.sub,
            ast.Mult: op.mul,
            ast.Div: op.truediv,
        }
        return operations[type(op)](left, right)

    def shell(self):
        while True:
            statement = input('>>> ')
            if statement.lower() == 'exit()':
                break
            elif '=' in statement:
                var, expr = statement.split('=')
                self.variables[var.strip()] = self.execute(expr)
            else:
                print(self.execute(statement))

if __name__ == '__main__':
    runtime = Runtime()
    runtime.shell()
```

