# user_account_management.py
import hashlib

class AccountPublicView:
    def view_public_account(self, user):
        return {"username": user.username, "email": user.email}

class ChangePasswordView:
    def change_password(self, user, old_password, new_password):
        if user.password == hashlib.sha256(old_password.encode()).hexdigest():
            user.password = hashlib.sha256(new_password.encode()).hexdigest()
        else:
            raise ValueError("Incorrect password")

class Login:
    def login(self, user, password):
        if user.password == hashlib.sha256(password.encode()).hexdigest():
            user.is_logged_in = True
        else:
            raise ValueError("Incorrect password")

class Logout:
    def logout(self, user):
        user.is_logged_in = False

class RegistrationView:
    def register(self, username, email, password):
        return {"username": username, "email": email, "password": hashlib.sha256(password.encode()).hexdigest(), "is_logged_in": False}

class AccountPropertiesView:
    def view_properties(self, user):
        return {"username": user.username, "email": user.email}

class UpdateAccountPicture:
    def update_picture(self, user, picture):
        user.picture = picture

class VerifyEmail:
    def verify_email(self, user, verification_code):
        if user.verification_code == verification_code:
            user.email_verified = True
        else:
            raise ValueError("Incorrect verification code")

class RatingView:
    def view_ratings(self, user):
        return user.ratings

class PostRatingView:
    def post_rating(self, user, rating):
        user.ratings.append(rating)

class LoggedInRatingView:
    def view_ratings(self, user):
        if user.is_logged_in:
            return user.ratings
        else:
            raise ValueError("User not logged in")
