        Login().login(self.user, "testpassword")
        self.assertTrue(self.user["is_logged_in"])

    def test_logout(self):
        Login().login(self.user, "testpassword")
        Logout().logout(self.user)
        self.assertFalse(self.user["is_logged_in"])

    def test_change_password(self):
        ChangePasswordView().change_password(self.user, "testpassword", "newpassword")
        self.assertEqual(self.user["password"], hashlib.sha256("newpassword".encode()).hexdigest())

    def test_view_public_account(self):
