def convert_to_seconds(milliseconds):
    return milliseconds / 1000.0

def process_chapter(chapter):
    start_time = convert_to_seconds(int(chapter['START']))
    end_time = convert_to_seconds(int(chapter['END']))
    type_code = '3' if chapter['title'] == 'Advertisement' else '1'
    return f"{start_time}\t{end_time}\t{type_code}"

def process_chapters(chapters):
    return [process_chapter(chapter) for chapter in chapters]

def read_chapters_from_file(filename):
    with open(filename, 'r') as file:
        lines = file.readlines()

    chapters = []
    current_chapter = {}

    for line in lines:
        line = line.strip()
        if line.startswith('['):
            if current_chapter:
                chapters.append(current_chapter)
            current_chapter = {}
        else:
            key, value = line.split('=')
            current_chapter[key] = value

    if current_chapter:
        chapters.append(current_chapter)

    return chapters

def write_edl_to_file(filename, edl):
    with open(filename, 'w') as file:
        for line in edl:
            file.write(line + '\n')

def main():
    chapters = read_chapters_from_file('chapters.txt')
    edl = process_chapters(chapters)
    write_edl_to_file('edl.txt', edl)

if __name__ == "__main__":
    main()
```

