class QueueDelta:
    def __init__(self):
        self.added = []
        self.removed = []
        self.penalty_updated = []

    def calculate(self, old_queues, new_queues):
        if not isinstance(old_queues, list) or not isinstance(new_queues, list):
            raise ValueError("Inputs must be lists")

        old_queues_dict = {queue['id']: queue for queue in old_queues}
        new_queues_dict = {queue['id']: queue for queue in new_queues}

        self.added = [queue for id, queue in new_queues_dict.items() if id not in old_queues_dict]
        self.removed = [queue for id, queue in old_queues_dict.items() if id not in new_queues_dict]
        self.penalty_updated = [new_queues_dict[id] for id in old_queues_dict if old_queues_dict[id]['penalty'] != new_queues_dict[id]['penalty']]

        return self


class OnAgentUpdatedManager:
    def __init__(self, add_to_queue_action, remove_from_queue_action, update_penalty_action):
        self.add_to_queue_action = add_to_queue_action
        self.remove_from_queue_action = remove_from_queue_action
        self.update_penalty_action = update_penalty_action
        self.old_queues = []

    def on_agent_updated(self, agent):
        if not isinstance(agent, dict) or 'queues' not in agent:
            raise ValueError("Invalid agent object")

        new_queues = agent['queues']
        delta = QueueDelta().calculate(self.old_queues, new_queues)

        for queue in delta.added:
            self.add_to_queue_action(agent, queue)

        for queue in delta.removed:
            self.remove_from_queue_action(agent, queue)

        for queue in delta.penalty_updated:
            self.update_penalty_action(agent, queue)

        self.old_queues = new_queues
