def string_operations(s, operations):
    results = []
    for operation in operations:
        op = operation[0]
        if op == "slice":
            if len(operation) != 3:
                raise ValueError("Invalid number of parameters for 'slice' operation")
            start, end = operation[1:]
            try:
                results.append(s[start:end])
            except IndexError:
                results.append("")
        elif op == "check":
            if len(operation) != 2:
                raise ValueError("Invalid number of parameters for 'check' operation")
            sub = operation[1]
            results.append(sub in s)
        elif op == "concat":
            if len(operation) != 2:
                raise ValueError("Invalid number of parameters for 'concat' operation")
            str_to_add = operation[1]
            results.append(s + str_to_add)
        elif op == "format":
            if len(operation) < 2:
                raise ValueError("Invalid number of parameters for 'format' operation")
            values = operation[1:]
            if s.count("{}") != len(values):
                raise ValueError("Incorrect number of placeholders in string for 'format' operation")
            results.append(s.format(*values))
        else:
            raise ValueError(f"Unsupported operation: {op}")
    return results
