```python
import os
import requests
from bs4 import BeautifulSoup
import time

def get_soup(url):
    try:
        response = requests.get(url)
        response.raise_for_status()
    except requests.exceptions.HTTPError as errh:
        print ("HTTP Error:", errh)
        return None
    except requests.exceptions.ConnectionError as errc:
        print ("Error Connecting:", errc)
        return None
    except requests.exceptions.Timeout as errt:
        print ("Timeout Error:", errt)
        return None
    except requests.exceptions.RequestException as err:
        print ("Something went wrong", err)
        return None
    return BeautifulSoup(response.text, 'html.parser')

def download_file(url, output_dir):
    local_filename = url.split('/')[-1]
    file_path = os.path.join(output_dir, local_filename)
    try:
        with requests.get(url, stream=True) as r:
            r.raise_for_status()
            with open(file_path, 'wb') as f:
                for chunk in r.iter_content(chunk_size=8192): 
                    f.write(chunk)
        print(f"Downloaded {local_filename}")
    except requests.exceptions.HTTPError as errh:
        print ("HTTP Error:", errh)
    except requests.exceptions.ConnectionError as errc:
        print ("Error Connecting:", errc)
    except requests.exceptions.Timeout as errt:
        print ("Timeout Error:", errt)
    except requests.exceptions.RequestException as err:
        print ("Something went wrong", err)

def download_all_tiles(data_type, output_dir):
    base_url = "https://srtm.csi.cgiar.org"
    soup = get_soup(base_url)
    if soup is None:
        return
    for link in soup.find_all('a'):
        href = link.get('href')
        if href.endswith(data_type):
            download_file(base_url + '/' + href, output_dir)

def download_specific_tile(tile_name, data_type, output_dir):
    base_url = "https://srtm.csi.cgiar.org"
    soup = get_soup(base_url)
    if soup is None:
        return
    for link in soup.find_all('a'):
        href = link.get('href')
        if href.endswith(data_type) and tile_name in href:
            download_file(base_url + '/' + href, output_dir)
            return
    print(f"Tile {tile_name} not found")

def main():
    data_type = input("Enter the type of data (GeoTIFF or ASCII): ")
    output_dir = input("Enter the output directory to store the downloaded tiles: ")
    specific_tile = input("Do you want to download a specific tile? (yes/no): ")
    if specific_tile.lower() == 'yes':
        tile_name = input("Enter the name of the specific tile: ")
        download_specific_tile(tile_name, data_type, output_dir)
    else:
        download_all_tiles(data_type, output_dir)

if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        print("\nDownload interrupted by user")
```

