```python
import torch
from torch import nn

class ImageDiffusionSampler:
    def __init__(self, model: nn.Module, device: torch.device):
        self.model = model.to(device)
        self.device = device

    def sample_image(self, num_steps: int, initial_latent: torch.Tensor = None):
        if initial_latent is None:
            initial_latent = torch.randn(1, self.model.latent_dim).to(self.device)
        else:
            initial_latent = initial_latent.to(self.device)

        for t in range(num_steps):
            noised_latent = self.add_noise(initial_latent, t)
            initial_latent = self.model(noised_latent, t)

        return initial_latent

    def apply_mask(self, noisy_latent: torch.Tensor, original_latent: torch.Tensor, mask: torch.Tensor, timestep: int):
        masked_latent = noisy_latent * (1 - mask) + original_latent * mask
        return self.add_noise(masked_latent, timestep)

    def add_noise(self, latent: torch.Tensor, timestep: int, noise: torch.Tensor = None):
        if noise is None:
            noise = torch.randn_like(latent)
        else:
            noise = noise.to(self.device)

        beta = self.model.beta_schedule[timestep]
        noised_latent = latent + noise * beta
        return noised_latent
