import numpy as np
import pandas as pd
import scipy.ndimage
import cupyx.scipy.ndimage
import time
import random

class ImageBench:
    def __init__(self, image_shapes, filter_sizes, modes, dtypes, seed=None):
        self.image_shapes = image_shapes
        self.filter_sizes = filter_sizes
        self.modes = modes
        self.dtypes = dtypes
        self.seed = seed
        self.results = []

    def generate_image(self, shape):
        if self.seed is not None:
            np.random.seed(self.seed)
        return np.random.rand(*shape).astype(self.dtype)

    def benchmark(self):
        for shape in self.image_shapes:
            for size in self.filter_sizes:
                for mode in self.modes:
                    for dtype in self.dtypes:
                        self.dtype = dtype
                        image = self.generate_image(shape)
                        self.run_benchmark(image, size, mode)

    def run_benchmark(self, image, size, mode):
        raise NotImplementedError

    def save_results(self, filename):
        df = pd.DataFrame(self.results, columns=['shape', 'size', 'mode', 'dtype', 'device', 'time'])
        df.to_csv(filename + '.csv')
        df.to_pickle(filename + '.pkl')
        df.to_markdown(filename + '.md')

class FilterBench(ImageBench):
    def run_benchmark(self, image, size, mode):
        for device in ['cpu', 'gpu']:
            start = time.time()
            if device == 'cpu':
                scipy.ndimage.uniform_filter(image, size, mode=mode)
            else:
                cupyx.scipy.ndimage.uniform_filter(cupy.array(image), size, mode=mode)
            end = time.time()
            self.results.append((shape, size, mode, dtype, device, end - start))

class ConvolveBench(ImageBench):
    def run_benchmark(self, image, size, mode):
        for device in ['cpu', 'gpu']:
            start = time.time()
            if device == 'cpu':
                scipy.ndimage.convolve(image, size, mode=mode)
            else:
                cupyx.scipy.ndimage.convolve(cupy.array(image), size, mode=mode)
            end = time.time()
            self.results.append((shape, size, mode, dtype, device, end - start))

# Usage
