from aws_lambda_powertools import Logger, Metrics, Tracer
from botocore.exceptions import BotoCoreError, ClientError

logger = Logger()
metrics = Metrics()
tracer = Tracer()

s3 = boto3.client('s3')

@metrics.log_metrics(capture_cold_start_metric=True)
@logger.inject_lambda_context(log_event=True)
@tracer.capture_lambda_handler
def lambda_handler(event, context):
    bucket_name = event['Records'][0]['s3']['bucket']['name']
    file_key = event['Records'][0]['s3']['object']['key']

    try:
        obj = s3.get_object(Bucket=bucket_name, Key=file_key)
        content = obj['Body'].read().decode('utf-8')
    except ClientError as e:
        if e.response['Error']['Code'] == 'NoSuchKey':
            logger.error('The object does not exist')
            return {'status': 'error', 'message': 'The object does not exist'}
        else:
            logger.exception('An error occurred')
            raise
    except UnicodeDecodeError:
        logger.error('Decoding error')
        return {'status': 'error', 'message': 'Decoding error'}
    except BotoCoreError as e:
        logger.exception('An error occurred')
        raise

    logger.info('S3 object content', extra={'content': content})
    metrics.add_metric(name="S3ObjectProcessed", unit="Count", value=1)

    return {'status': 'success', 'content': content, 'event': event}
