```python
class MetadataFormatType:
    def __init__(self, prefix, schema, namespace):
        self.prefix = prefix
        self.schema = schema
        self.namespace = namespace

class ListMetadataFormatsType:
    def __init__(self):
        self.formats = []

    def add_format(self, format):
        if not isinstance(format, MetadataFormatType):
            raise ValueError("The format must be an instance of MetadataFormatType")
        for f in self.formats:
            if f.prefix == format.prefix:
                raise ValueError("A format with the same prefix already exists")
        self.formats.append(format)

    def get_formats(self):
        return self.formats

    def find_format(self, prefix):
        if prefix == "":
            return None
        for f in self.formats:
            if f.prefix == prefix:
                return f
        return None
```

