```python
import uuid

class TransactionProtocol:
    def __init__(self):
        self.transactions = {}

    def create_transaction(self, sender, receiver, amount, currency):
        if amount < 0:
            raise ValueError("Amount cannot be negative")

        transaction_id = str(uuid.uuid4())
        transaction = {
            'sender': sender,
            'receiver': receiver,
            'amount': amount,
            'currency': currency,
            'transaction_id': transaction_id
        }
        self.transactions[transaction_id] = transaction
        return transaction

    def create_confirmation(self, transaction_id, success):
        if transaction_id not in self.transactions:
            raise ValueError("Transaction ID not found")

        confirmation = {
            'transaction_id': transaction_id,
            'success': success
        }
        return confirmation

    def check_consistency(self, message):
        if 'transaction_id' not in message:
            return False

        if 'sender' in message and 'receiver' in message and 'amount' in message and 'currency' in message:
            if message['amount'] < 0:
                return False
        elif 'success' in message:
            if message['transaction_id'] not in self.transactions:
                return False
        else:
            return False

        return True
```

