Here is a Python program that fulfills the requirements:

```python
import os
import json
import shutil
import pytest

def import_data(file_path):
    try:
        with open(file_path, 'r') as file:
            data = json.load(file)
        return data
    except FileNotFoundError:
        print(f"File {file_path} not found.")
        return {}
    except json.JSONDecodeError:
        print(f"Invalid JSON format in {file_path}.")
        return {}

def extract_trait_values(data, trait):
    try:
        trait_values = [item[trait] for item in data]
        return trait_values
    except KeyError:
        print(f"Trait {trait} not found in data.")
        return []

def classify_images(data, trait, threshold, base_path):
    for item in data:
        try:
            image_id = item['image_id']
            trait_value = item[trait]
            range_ = 'high-range' if trait_value > threshold else 'low-range'
            src_path = os.path.join(base_path, image_id)
            dest_path = os.path.join(base_path, 'classification', image_id, trait, range_)
            shutil.copy2(src_path, dest_path)
        except KeyError:
            print(f"Image ID or trait {trait} not found in data.")

def test_import_data():
    assert import_data('non_existent_file.json') == {}
    assert import_data('test_data.json') == {'image_id': '123', 'warmth': 0.5}

def test_extract_trait_values():
