```python
import requests
import datetime
import smtplib
from email.mime.multipart import MIMEMultipart
from email.mime.text import MIMEText

class WebMonitoringService:
    @staticmethod
    def get_page(url):
        try:
            response = requests.get(url, verify=False)
            response.raise_for_status()
        except requests.exceptions.HTTPError as errh:
            print ("HTTP Error:", errh)
            raise
        except requests.exceptions.ConnectionError as errc:
            print ("Error Connecting:", errc)
            raise
        except requests.exceptions.Timeout as errt:
            print ("Timeout Error:", errt)
            raise
        except requests.exceptions.RequestException as err:
            print ("Something went wrong", err)
            raise
        return response.text

    @staticmethod
    def epoch_to_datetime(seconds):
        return datetime.datetime.utcfromtimestamp(seconds)

    @staticmethod
    def datetime_to_epoch(timestamp):
        return (timestamp - datetime.datetime(1970, 1, 1)).total_seconds()

    @staticmethod
    def get_UTC_now():
        return datetime.datetime.utcnow()

    @staticmethod
    def build_URL(baseURL, params):
        return baseURL.format(**params)

    @staticmethod
    def send_email(subject, message, recipients, email_config):
        msg = MIMEMultipart()
        msg['From'] = email_config['user']
        msg['To'] = ', '.join(recipients)
        msg['Subject'] = subject
        msg.attach(MIMEText(message))

        try:
            with smtplib.SMTP_SSL(email_config['smtp_server'], email_config['port']) as server:
                server.login(email_config['user'], email_config['password'])
                server.sendmail(email_config['user'], recipients, msg.as_string())
        except smtplib.SMTPException as e:
            print ("Error: unable to send email", e)
            raise
