class JobSystem:
    def __init__(self):
        self.jobs = {}

    def job(self, depends_on=None, desc=""):
        def decorator(func):
            name = func.__name__
            if depends_on and depends_on not in self.jobs:
                raise ValueError(f"Invalid dependency: {depends_on}")
            self.jobs[name] = {"func": func, "depends_on": depends_on, "desc": desc}
            return func
        return decorator

    def run_job(self, name):
        if name not in self.jobs:
            raise ValueError(f"Invalid job name: {name}")
        job = self.jobs[name]
        if job["depends_on"]:
            self.run_job(job["depends_on"])
        job["func"]()

    def list_jobs(self):
        for name, job in self.jobs.items():
            print(f"Job: {name}\nDescription: {job['desc']}\nDepends on: {job['depends_on']}\n")


# Usage
job_system = JobSystem()

@job_system.job(desc="This is the first job")
def job1():
    print("Running job1")

@job_system.job(desc="This is the second job", depends_on="job1")
def job2():
    print("Running job2")

@job_system.job(desc="This is the third job", depends_on="job2")
