import json
import math

class Map:
    def __init__(self, map_id, name, version, roads):
        self.map_id = map_id
        self.name = name
        self.version = version
        self.roads = roads

class Road:
    def __init__(self, road_id, name, type, start_pos, length, bearing, connections, lanes):
        self.road_id = road_id
        self.name = name
        self.type = type
        self.start_pos = start_pos
        self.length = length
        self.bearing = bearing
        self.connections = connections
        self.lanes = lanes

class Lane:
    def __init__(self, lane_id, name, width, points, distance_points, intercept):
        self.lane_id = lane_id
        self.name = name
        self.width = width
        self.points = points
        self.distance_points = distance_points
        self.intercept = intercept

def read_map_from_json(file_name):
    try:
        with open(file_name, 'r') as file:
            data = json.load(file)
            roads = []
            for road_data in data['roads']:
                lanes = []
                for lane_data in road_data['lanes']:
                    lanes.append(Lane(lane_data['lane_id'], lane_data['name'], lane_data['width'], lane_data['points'], lane_data['distance_points'], lane_data['intercept']))
                roads.append(Road(road_data['road_id'], road_data['name'], road_data['type'], road_data['start_pos'], road_data['length'], road_data['bearing'], road_data['connections'], lanes))
            return Map(data['map_id'], data['name'], data['version'], roads)
    except FileNotFoundError:
        print(f"Error: File {file_name} not found.")
    except json.JSONDecodeError:
        print(f"Error: Invalid JSON in file {file_name}.")
    except KeyError as e:
        print(f"Error: Missing key {e} in JSON file.")

def to_radians(degrees):
    return degrees * math.pi / 180

def calculate_end_pos(start_pos, length, bearing):
    bearing_rad = to_radians(bearing)
    end_x = start_pos[0] + length * math.cos(bearing_rad)
    end_y = start_pos[1] + length * math.sin(bearing_rad)
    return (end_x, end_y)

def generate_distance_points(start_pos, end_pos, num_points):
    distance_points = []
    for i in range(num_points):
        ratio = i / (num_points - 1)
        x = start_pos[0] + ratio * (end_pos[0] - start_pos[0])
        y = start_pos[1] + ratio * (end_pos[1] - start_pos[1])
        distance_points.append((x, y))
    return distance_points

def print_map(map):
    print(f"Map ID: {map.map_id}, Name: {map.name}, Version: {map.version}")
    for road in map.roads:
        print(f"Road ID: {road.road_id}, Name: {road.name}, Type: {road.type}, Start Position: {road.start_pos}, Length: {road.length}, Bearing: {road.bearing}, Connections: {road.connections}")
        for lane in road.lanes:
            print(f"Lane ID: {lane.lane_id}, Name: {lane.name}, Width: {lane.width}, Points: {lane.points}, Distance Points: {lane.distance_points}, Intercept: {lane.intercept}")

