import networkx as nx
import matplotlib.pyplot as plt
import time
import random
import math

def euclidean_distance(p1, p2):
    return math.sqrt((p1[0] - p2[0])**2 + (p1[1] - p2[1])**2)

def generate_graph(n):
    G = nx.Graph()
    nodes = [(random.randint(0, 100), random.randint(0, 100)) for _ in range(n)]
    for i in range(n):
        for j in range(i+1, n):
            G.add_edge(i, j, weight=euclidean_distance(nodes[i], nodes[j]))
    return G, nodes

def check_constraints(G):
    if not nx.is_connected(G):
        return False
    if max(nx.all_pairs_dijkstra_path_length(G))[1] > 4:
        return False
    for node in G.nodes:
        if G.degree[node] != 3:
            return False
    return True

def greedy_local_search(G):
    start_time = time.time()
    for _ in range(100):
        edges = list(G.edges(data=True))
        edges.sort(key=lambda x: x[2]['weight'], reverse=True)
        G.remove_edge(*edges[0][:2])
        if not check_constraints(G):
            G.add_edge(*edges[0][:2])
    print("Greedy Local Search Runtime: ", time.time() - start_time)
    return G

def original_heuristic(G, nodes):
    start_time = time.time()
    G = nx.Graph()
    for i in range(len(nodes)):
        for j in range(i+1, len(nodes)):
            G.add_edge(i, j, weight=euclidean_distance(nodes[i], nodes[j]))
    edges = list(G.edges(data=True))
    edges.sort(key=lambda x: x[2]['weight'])
    for edge in edges:
        if not check_constraints(G):
            G.remove_edge(*edge[:2])
    print("Original Heuristic Runtime: ", time.time() - start_time)
    return G

def main():
    n = 10
    G, nodes = generate_graph(n)
    print("Nodes: ", nodes)
    print("Total Cost Before Optimization: ", sum(weight for _, __, weight in G.edges(data='weight')))
    G = greedy_local_search(G)
    print("Total Cost After Greedy Local Search: ", sum(weight for _, __, weight in G.edges(data='weight')))
    G = original_heuristic(G, nodes)
    print("Total Cost After Original Heuristic: ", sum(weight for _, __, weight in G.edges(data='weight')))

if __name__ == "__main__":
    main()
