```python
import scrapy
from scrapy.crawler import CrawlerProcess

class JobSpider(scrapy.Spider):
    name = 'job_spider'
    start_urls = ['http://www.jobboard.com/jobs']

    custom_settings = {
        'FEED_FORMAT': 'json',
        'FEED_URI': 'job_data.json',
        'LOG_ENABLED': True,
        'ROBOTSTXT_OBEY': True,
    }

    def parse(self, response):
        for job in response.css('div.job'):
            yield {
                'job_id': job.css('span.job_id::text').get(),
                'job_title': job.css('span.job_title::text').get(),
                'company_name': job.css('span.company_name::text').get(),
                # Add other fields here...
            }

        next_page = response.css('li.next a::attr(href)').get()
        if next_page is not None:
            yield response.follow(next_page, self.parse)


class CompanySpider(scrapy.Spider):
    name = 'company_spider'
    start_urls = ['http://www.jobboard.com/companies']

    custom_settings = {
        'FEED_FORMAT': 'json',
        'FEED_URI': 'company_data.json',
        'LOG_ENABLED': True,
        'ROBOTSTXT_OBEY': True,
    }

    def parse(self, response):
        for company in response.css('div.company'):
            yield {
                'company_name': company.css('span.company_name::text').get(),
                # Add other fields here...
            }

        next_page = response.css('li.next a::attr(href)').get()
        if next_page is not None:
            yield response.follow(next_page, self.parse)


process = CrawlerProcess()
process.crawl(JobSpider)
process.crawl(CompanySpider)
process.start()
```

