Here is a Python program that implements a Convolutional Neural Network (CNN) for image classification. This program uses TensorFlow, a popular deep learning library.

```python
import tensorflow as tf
import numpy as np
import resize_data
import batch_maker

class ConvNet:
    def __init__(self, n_classes):
        self.n_classes = n_classes
        self.x = tf.placeholder(tf.float32, [None, 30, 30, 1])
        self.y = tf.placeholder(tf.float32, [None, self.n_classes])
        self.keep_prob = tf.placeholder(tf.float32)

        self.weights = {
            'wc1': tf.Variable(tf.random_normal([5, 5, 1, 32])),
            'wc2': tf.Variable(tf.random_normal([5, 5, 32, 64])),
            'wd1': tf.Variable(tf.random_normal([15 * 15 * 64, 1024])),
            'out': tf.Variable(tf.random_normal([1024, self.n_classes]))
        }

        self.biases = {
            'bc1': tf.Variable(tf.random_normal([32])),
            'bc2': tf.Variable(tf.random_normal([64])),
            'bd1': tf.Variable(tf.random_normal([1024])),
            'out': tf.Variable(tf.random_normal([self.n_classes]))
        }

        self.pred = self.conv_net(self.x, self.weights, self.biases, self.keep_prob)

    def conv2d(self, x, W, b, strides=1):
        x = tf.nn.conv2d(x, W, strides=[1, strides, strides, 1], padding='SAME')
        x = tf.nn.bias_add(x, b)
        return tf.nn.relu(x)

    def maxpool2d(self, x, k=2):
        return tf.nn.max_pool(x, ksize=[1, k, k, 1], strides=[1, k, k, 1], padding='SAME')

    def conv_net(self, x, weights, biases, dropout):
        conv1 = self.conv2d(x, weights['wc1'], biases['bc1'])
        conv1 = self.maxpool2d(conv1, k=2)

        conv2 = self.conv2d(conv1, weights['wc2'], biases['bc2'])
        conv2 = self.maxpool2d(conv2, k=2)

        fc1 = tf.reshape(conv2, [-1, weights['wd1'].get_shape().as_list()[0]])
        fc1 = tf.add(tf.matmul(fc1, weights['wd1']), biases['bd1'])
        fc1 = tf.nn.relu(fc1)
        fc1 = tf.nn.dropout(fc1, dropout)

        out = tf.add(tf.matmul(fc1, weights['out']), biases['out'])
        return out

    def load_model(self, sess, model_path):
        saver = tf.train.Saver()
        saver.restore(sess, model_path)

    def preprocess_image(self, image):
        if isinstance(image, str):
            image = resize_data.resize_image(image)
        elif isinstance(image, np.ndarray):
            image = resize_data.resize_array(image)
        return image

    def classify_image(self, sess, image, batch_size=100):
        image = self.preprocess_image(image)
        batch_x = batch_maker.make_batch(image, batch_size)
        prediction = sess.run(self.pred, feed_dict={self.x: batch_x, self.keep_prob: 1.0})
        return np.argmax(prediction, 1)

    def classify_images_from_command_line(self, sess):
        while True:
            image_path = input("Enter the path of the image to classify: ")
            if image_path.lower() == 'exit':
                break
            print(self.classify_image(sess, image_path))
```

This program defines a ConvNet class that encapsulates the functionality of the CNN. The `__init__` method initializes the placeholders for the input data, the weights and biases for the layers, and the model itself. The `conv2d` and `maxpool2d` methods implement the 2D convolution and max-pooling operations, respectively. The `conv_net` method defines the structure of the CNN. The `load_model` method restores a pre-trained model from a file. The `preprocess_image` method resizes the input image to the required dimensions. The `classify_image` method classifies a single image or a batch of images and returns the predicted category indices. The `classify_images_from_command_line` method provides a command-line interface to classify images specified by the user.

