```python
import nltk
from nltk.corpus import wordnet
from dateutil.parser import parse

def nlp_analyze(sentence, word_classes=None, skip_first=False):
    if not sentence:
        return {'lastnoun': None, 'nouns': [], 'numbers': [], 'date': None, 'word_classes': []}

    tokens = nltk.word_tokenize(sentence)
    pos_tags = nltk.pos_tag(tokens)

    nouns = [word for word, pos in pos_tags if pos in ['NN', 'NNS', 'NNP', 'NNPS']]
    numbers = [int(nltk.word_tokenize(word)[0]) for word, pos in pos_tags if pos == 'CD']
    dates = [parse(word).strftime('%Y-%m-%d %H:%M:%S') for word, pos in pos_tags if pos == 'CD' and 
             word.replace('.', '').isdigit() == False]

    word_classes_found = []
    if word_classes:
        for word_class, words in word_classes:
            for word in words:
                if word in tokens:
                    word_classes_found.append(word_class)

    result = {
        'lastnoun': nouns[-1] if nouns else None,
        'nouns': nouns[1:] if skip_first and nouns else nouns,
        'numbers': numbers,
        'date': dates[0] if dates else None,
        'word_classes': word_classes_found
    }

    return result
```

