```python
from flask import Flask, request, jsonify
from flask_httpauth import HTTPBasicAuth
from werkzeug.security import generate_password_hash, check_password_hash

app = Flask(__name__)
auth = HTTPBasicAuth()

users = {
    "admin": generate_password_hash("password"),
}

leaks = {}

@auth.verify_password
def verify_password(username, password):
    if username in users and \
            check_password_hash(users.get(username), password):
        return username

@app.route('/api/v2/leak/general/', methods=['POST'])
@auth.login_required
def create_leak():
    if not request.json or not 'url' in request.json or not 'leak_id' in request.json:
        return jsonify({'status': 'error', 'message': 'Missing parameters'}), 400

    leak_id = request.json['leak_id']
    url = request.json['url']

    if leak_id in leaks:
        return jsonify({'status': 'error', 'message': 'Leak already exists'}), 400

    leaks[leak_id] = url
    return jsonify({'status': 'success', 'message': 'Leak created', 'data': {'leak_id': leak_id, 'url': url}}), 201

@app.route('/api/v2/leak/general/', methods=['GET'])
@auth.login_required
def get_leaks():
    return jsonify({'status': 'success', 'data': leaks})

@app.route('/api/v2/leak/general/<leak_id>', methods=['GET'])
@auth.login_required
def get_leak(leak_id):
    if leak_id not in leaks:
        return jsonify({'status': 'error', 'message': 'Leak not found'}), 404

    return jsonify({'status': 'success', 'data': {'leak_id': leak_id, 'url': leaks[leak_id]}})

@app.route('/api/v2/leak/general/<leak_id>', methods=['DELETE'])
@auth.login_required
def delete_leak(leak_id):
    if leak_id not in leaks:
        return jsonify({'status': 'error', 'message': 'Leak not found'}), 404

    del leaks[leak_id]
    return jsonify({'status': 'success', 'message': 'Leak deleted'})

if __name__ == '__main__':
    app.run(debug=True)
```

