```python
import os
import requests
from jira import JIRA

def authenticate():
    try:
        jira_options = {'server': 'https://issues.apache.org/jira'}
        jira = JIRA(options=jira_options, basic_auth=(os.environ['JIRA_USERNAME'], os.environ['JIRA_PASSWORD']))
        return jira
    except Exception as e:
        print(f"Authentication failed: {str(e)}")
        return None

def fetch_issues(jira, fix_version):
    try:
        issues = jira.search_issues(f'fixVersion = {fix_version} AND resolution = Fixed OR resolution = Done')
        return issues
    except requests.exceptions.RequestException as e:
        print(f"Failed to fetch issues: {str(e)}")
        return []

def group_issues(issues, is_website):
    groups = {}
    for issue in issues:
        if is_website:
            key = issue.fields.project.name
        else:
            key = issue.fields.issuetype.name
        if key not in groups:
            groups[key] = []
        groups[key].append(issue)
    return groups

def sort_issues(groups):
    for key in groups:
        groups[key] = sorted(groups[key], key=lambda issue: issue.key)
    return groups

def format_output(groups, is_website):
    output = ""
    for key in sorted(groups.keys()):
        if is_website:
            output += f"\n## {key}\n"
        else:
            output += f"\n### {key}\n"
        for issue in groups[key]:
            output += f"- [{issue.key}] {issue.fields.summary}\n"
    return output

def main(fix_version, is_website):
    jira = authenticate()
    if jira is None:
        return
    issues = fetch_issues(jira, fix_version)
    groups = group_issues(issues, is_website)
    sorted_groups = sort_issues(groups)
    output = format_output(sorted_groups, is_website)
    print(output)

if __name__ == "__main__":
    import sys
    if len(sys.argv) < 2 or len(sys.argv) > 3:
        print("Usage: make_changelog.py $FIX_VERSION [$IS_WEBSITE]")
        sys.exit(1)
    fix_version = sys.argv[1]
    is_website = len(sys.argv) == 3 and sys.argv[2] == '1'
    main(fix_version, is_website)
```

This script can be executed from the command line with the following usage:

```
python make_changelog.py $FIX_VERSION [$IS_WEBSITE]
```

Where `$FIX_VERSION` is the version of the project for which the changelog is being generated, and `$IS_WEBSITE` is an optional argument that, if set to '1', indicates that the output should be formatted for the website.

Please note that this script assumes that the JIRA username and password are stored in the `JIRA_USERNAME` and `JIRA_PASSWORD` environment variables, respectively.

