from abc import ABC, abstractmethod

class Customer:
    def __init__(self, id, personal_info):
        self.id = id
        self.personal_info = personal_info

class Verification(ABC):
    @abstractmethod
    def verify(self, customer):
        pass

class CustomerVerificationResult:
    def __init__(self, customer_id, passed):
        self.customer_id = customer_id
        self.passed = passed

class CustomerVerifier:
    def __init__(self, verifications):
        self.verifications = verifications

    def verify(self, customer):
        if not customer.personal_info:
            return CustomerVerificationResult(customer.id, False)

        for verification in self.verifications:
            if not verification.verify(customer):
                return CustomerVerificationResult(customer.id, False)

        return CustomerVerificationResult(customer.id, True)
```

