import datetime
import dateutil.parser
import sys

class CongressError(Exception):
    def __init__(self, message, response=None, url=None):
        super().__init__(message)
        self.response = response
        self.url = url

class NotFound(CongressError):
    pass

def check_chamber(chamber):
    if chamber not in ['house', 'senate', 'both']:
        raise TypeError("Invalid chamber. It should be one of 'house', 'senate', or 'both'")

def get_congress(year):
    if year < 1789:
        raise CongressError("Congress did not exist before 1789")
    return (year - 1789) // 2 + 1

def parse_date(date):
    if isinstance(date, (datetime.datetime, datetime.date)):
        return date
    if 'dateutil' in sys.modules and hasattr(dateutil.parser, 'parse'):
        return dateutil.parser.parse(date)
    else:
        return datetime.datetime.strptime(date, "%Y-%m-%d")

def u(text):
    if isinstance(text, bytes):
        text = text.decode('utf-8')
    return text.replace('\r\n', '\n')

def get_offset(page):
    if page < 1:
        raise CongressError("Page number should be greater than 0")
    return (page - 1) * 20

CURRENT_CONGRESS = get_congress(datetime.datetime.now().year)
