from fastapi import FastAPI, HTTPException
from pydantic import BaseModel

app = FastAPI()

# In-memory data store
accounts = {}

class DepositWithdraw(BaseModel):
    amount: float

@app.get("/ping/")
async def ping():
    return {"ping": "pong"}

@app.get("/account/{account_id}/")
async def get_balance(account_id: int):
    if account_id not in accounts:
        raise HTTPException(status_code=404, detail="Account not found")
    return {"balance": accounts[account_id]}

@app.post("/account/{account_id}/deposit/")
async def deposit(account_id: int, deposit: DepositWithdraw):
    if deposit.amount <= 0:
        raise HTTPException(status_code=400, detail="Deposit amount must be positive")
    if account_id not in accounts:
        accounts[account_id] = 0
    accounts[account_id] += deposit.amount
    return {"balance": accounts[account_id]}

@app.post("/account/{account_id}/withdraw/")
async def withdraw(account_id: int, withdraw: DepositWithdraw):
    if withdraw.amount <= 0:
        raise HTTPException(status_code=400, detail="Withdrawal amount must be positive")
    if account_id not in accounts or accounts[account_id] < withdraw.amount:
        raise HTTPException(status_code=400, detail="Insufficient balance")
    accounts[account_id] -= withdraw.amount
    return {"balance": accounts[account_id]}
