```python
import hashlib
import os

class MockTestRunner:
    def __init__(self):
        self.tests = []
        self.results = []

    def add_test(self, test_name, test_type, expected_result):
        if test_type not in ['text', 'image', 'audio', 'virtual', 'reftest']:
            raise ValueError('Invalid test type')
        if expected_result is None:
            raise ValueError('Missing expected result')
        self.tests.append({
            'name': test_name,
            'type': test_type,
            'expected': expected_result
        })

    def run_tests(self):
        for test in self.tests:
            result = self.run_test(test)
            self.results.append(result)
        return self.summary()

    def run_test(self, test):
        if test['type'] == 'image':
            actual_result = self.get_image_checksum(test['expected'])
        elif test['type'] == 'audio':
            actual_result = self.get_audio_data(test['expected'])
        else:
            actual_result = test['expected']
        return {
            'name': test['name'],
            'expected': test['expected'],
            'actual': actual_result,
            'status': 'passed' if actual_result == test['expected'] else 'failed'
        }

    def summary(self):
        summary = {
            'passed': [],
            'failed': [],
            'skipped': []
        }
        for result in self.results:
            summary[result['status']].append(result)
        return summary

    def get_image_checksum(self, image_path):
        if not os.path.exists(image_path):
            return None
        with open(image_path, 'rb') as f:
            return hashlib.md5(f.read()).hexdigest()

    def get_audio_data(self, audio_path):
        if not os.path.exists(audio_path):
            return None
        with open(audio_path, 'rb') as f:
            return f.read()
