from typing import List, Callable
from VoIPController import VoIPController, Endpoint, CallState

class VoIPManager:
    def __init__(self):
        self.calls = {}
        self.controller = VoIPController()

    def start_call(self, call_id: int, endpoints: List[Endpoint], encryption_key: bytes, is_outgoing: bool):
        if not isinstance(call_id, int):
            raise TypeError("call_id must be an integer")
        if not isinstance(endpoints, list) or not all(isinstance(e, Endpoint) for e in endpoints):
            raise TypeError("endpoints must be a list of Endpoint objects")
        if not isinstance(encryption_key, bytes):
            raise TypeError("encryption_key must be a bytes object")
        if not isinstance(is_outgoing, bool):
            raise TypeError("is_outgoing must be a boolean")

        self.controller.start_call(call_id, endpoints, encryption_key, is_outgoing)
        self.calls[call_id] = self.controller.get_call(call_id)

    def end_call(self, call_id: int):
        if not isinstance(call_id, int):
            raise TypeError("call_id must be an integer")

        self.controller.end_call(call_id)
        del self.calls[call_id]

    def get_call_duration(self, call_id: int) -> float:
        if not isinstance(call_id, int):
            raise TypeError("call_id must be an integer")

        return self.calls[call_id].get_duration()

    def set_call_state_changed_handler(self, call_id: int, handler: Callable[[CallState], None]):
        if not isinstance(call_id, int):
            raise TypeError("call_id must be an integer")
        if not callable(handler):
            raise TypeError("handler must be a callable function")

        self.calls[call_id].set_state_changed_handler(handler)

    def set_call_audio_frame_handlers(self, call_id: int, send_handler: Callable[[int], bytes], recv_handler: Callable[[bytes], None]):
        if not isinstance(call_id, int):
            raise TypeError("call_id must be an integer")
        if not callable(send_handler):
            raise TypeError("send_handler must be a callable function")
        if not callable(recv_handler):
            raise TypeError("recv_handler must be a callable function")

        self.calls[call_id].set_audio_frame_handlers(send_handler, recv_handler)
```

This class uses a dictionary `self.calls` to keep track of all ongoing calls. When a call is started, it is added to the dictionary. When a call is ended, it is removed from the dictionary.

The `start_call`, `end_call`, `get_call_duration`, `set_call_state_changed_handler`, and `set_call_audio_frame_handlers` methods all validate their input parameters to ensure they are of the correct type and format. If an invalid parameter is provided, a `TypeError` is raised.

The `VoIPController` class is used to start, end, and manage the state of each call. The `VoIPController` class is assumed to have the following methods:

- `start_call(call_id: int, endpoints: List[Endpoint], encryption_key: bytes, is_outgoing: bool)`: Starts a new VoIP call.
- `end_call(call_id: int)`: Ends the call with the given call ID.
- `get_call(call_id: int)`: Returns the call with the given call ID.
- `Call.get_duration() -> float`: Returns the duration of the call in seconds.
- `Call.set_state_changed_handler(handler: Callable[[CallState], None])`: Sets a handler function that will be called when the state of the call changes.
- `Call.set_audio_frame_handlers(send_handler: Callable[[int], bytes], recv_handler: Callable[[bytes], None])`: Sets handler functions for sending and receiving audio frames.

