```python
import unittest

class TestValidator(unittest.TestCase):
    def setUp(self):
        self.validator = Validator()

    def test_validate_domain(self):
        self.assertTrue(self.validator.validate_domain('google.com'))
        self.assertFalse(self.validator.validate_domain('google..com'))

    def test_validate_ip(self):
        self.assertTrue(self.validator.validate_ip('192.168.0.1'))
        self.assertFalse(self.validator.validate_ip('256.168.0.1'))

    def test_format_date(self):
        self.assertEqual(self.validator.format_date('12-Dec-2020'), '12-Dec-2020')
        self.assertEqual(self.validator.format_date('1-Jan-2020'), '01-Jan-2020')
        self.assertEqual(self.validator.format_date('32-Dec-2020'), 'Invalid date format')

    def test_convert_month(self):
        self.assertEqual(self.validator.convert_month('1'), 'Jan')
        self.assertEqual(self.validator.convert_month('12'), 'Dec')
        self.assertEqual(self.validator.convert_month('13'), 'Invalid month')

    def test_convert_day(self):
        self.assertEqual(self.validator.convert_day('1'), '01')
        self.assertEqual(self.validator.convert_day('10'), '10')
        self.assertEqual(self.validator.convert_day('32'), 'Invalid day')
        self.assertEqual(self.validator.convert_day('a'), 'Invalid day')

if __name__ == '__main__':
    unittest.main()
