import re
import os
import time

def getCommon5():
    with open('common5.txt', 'r') as f:
        return f.read().splitlines()

def makePositionPattern(greenLetters):
    pattern = ''
    for letter in greenLetters:
        if letter:
            pattern += f'[^{letter}]*[{letter}][^{letter}]*'
        else:
            pattern += '.'
    return pattern

def makeNotPositionPattern(yellowLetters):
    pattern = ''
    for letter in yellowLetters:
        if letter:
            pattern += f'(^|[^{letter}])([^{letter}]*[{letter}][^{letter}]*){{0}}'
        else:
            pattern += '.'
    return pattern

def makeExcludePattern(badLetters):
    return f'[^{badLetters}]*'

def evaluateMatchingRules(word, greenPattern, yellowPattern, badPattern):
    return re.match(greenPattern, word) and re.match(yellowPattern, word) and re.match(badPattern, word)

def printWords(commonWords, uncommonWords):
    print("Common Words:")
    for word in commonWords:
        print(word)
    print("\nUncommon Words:")
    for word in uncommonWords:
        print(word)

def runProcess():
