```python
from collections import deque

def minimum_bridge_length(n, arr):
    # Check if the grid is valid
    if not all(len(row) == n for row in arr) or not all(el in (0, 1) for row in arr for el in row):
        return -1

    # Find all islands
    islands = []
    visited = [[False]*n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if arr[i][j] == 1 and not visited[i][j]:
                islands.append(bfs(arr, visited, i, j, n))

    # If there is only one island, return -1
    if len(islands) == 1:
        return -1

    # Find the minimum distance between two islands
    min_dist = float('inf')
    for i in range(len(islands)):
        for j in range(i+1, len(islands)):
            min_dist = min(min_dist, distance(islands[i], islands[j]))

    return min_dist-1

def bfs(arr, visited, x, y, n):
    dx = [-1, 0, 1, 0]
    dy = [0, 1, 0, -1]
    queue = deque([(x, y, 0)])
    visited[x][y] = True
    island = []
    while queue:
        x, y, dist = queue.popleft()
        island.append((x, y, dist))
        for i in range(4):
            nx, ny = x + dx[i], y + dy[i]
            if nx < 0 or nx >= n or ny < 0 or ny >= n or visited[nx][ny] or arr[nx][ny] == 0:
                continue
            visited[nx][ny] = True
            queue.append((nx, ny, dist+1))
    return island

def distance(island1, island2):
    min_dist = float('inf')
    for x1, y1, dist1 in island1:
        for x2, y2, dist2 in island2:
            min_dist = min(min_dist, abs(x1-x2) + abs(y1-y2))
    return min_dist
```

This solution works by first finding all islands in the grid. Then, for each pair of islands, it calculates the minimum distance between them. The minimum distance is the minimum length of a bridge that connects any two islands.

The `bfs` function is used to find all squares of an island. The `distance` function calculates the minimum distance between two islands.

The time complexity of this solution is O(n^2) because in the worst case, we need to visit every square in the grid once. The space complexity is also O(n^2) because we need to store the visited squares and the islands.

