```python
class Device:
    AVAILABLE = 'available'
    UNAVAILABLE = 'unavailable'

    def __init__(self, name, state=AVAILABLE):
        self.name = name
        self.state = state

    def is_available(self):
        return self.state == self.AVAILABLE

    def set_state(self, state):
        self.state = state


class Switch(Device):
    ON = 'on'
    OFF = 'off'

    def __init__(self, name, state=Device.AVAILABLE, switch_state=OFF):
        super().__init__(name, state)
        self.switch_state = switch_state

    def turn_on(self):
        if self.is_available():
            self.switch_state = self.ON
        else:
            raise Exception(f'{self.name} is not available')

    def turn_off(self):
        if self.is_available():
            self.switch_state = self.OFF
        else:
            raise Exception(f'{self.name} is not available')

    def toggle(self):
        if self.is_available():
            self.switch_state = self.ON if self.switch_state == self.OFF else self.OFF
        else:
            raise Exception(f'{self.name} is not available')


class Cover(Device):
    OPEN = 'open'
    CLOSED = 'closed'

    def __init__(self, name, state=Device.AVAILABLE, cover_state=CLOSED):
        super().__init__(name, state)
        self.cover_state = cover_state

    def open(self):
        if self.is_available():
            self.cover_state = self.OPEN
        else:
            raise Exception(f'{self.name} is not available')

    def close(self):
        if self.is_available():
            self.cover_state = self.CLOSED
        else:
            raise Exception(f'{self.name} is not available')


class SmartHomeSystem:
    def __init__(self):
        self.devices = {}

    def add_device(self, device):
        self.devices[device.name] = device

    def get_device(self, name):
        return self.devices.get(name)

    def get_device_state(self, name):
        device = self.get_device(name)
        if device:
            return device.state
        else:
            return None

    def get_device_switch_state(self, name):
        device = self.get_device(name)
        if isinstance(device, Switch):
            return device.switch_state
        else:
            return None

    def get_device_cover_state(self, name):
        device = self.get_device(name)
        if isinstance(device, Cover):
            return device.cover_state
        else:
            return None
