class BuyContract:
    def __init__(self, vehicle_price, vehicle_mileage, vehicle_age, customer_type):
        if vehicle_price < 0 or vehicle_mileage < 0 or vehicle_age < 0:
            raise ValueError("Vehicle price, mileage and age must be non-negative.")
        self.vehicle_price = vehicle_price
        self.vehicle_mileage = vehicle_mileage
        self.vehicle_age = vehicle_age
        self.customer_type = customer_type

    def total_value(self):
        base_price = self.vehicle_price - (self.vehicle_mileage * 0.02) - (self.vehicle_age * 0.1)
        if self.customer_type == 'Employee':
            total_value = base_price * 0.9
        else:
            total_value = base_price
        total_value *= 1.07  # 7% tax
        return total_value

    def monthly_value(self, num_payments):
        if num_payments <= 0:
            raise ValueError("Number of payments must be a positive integer.")
        return self.total_value() / num_payments


class LeaseContract:
    def __init__(self, vehicle_type, lease_length):
        if lease_length <= 0:
            raise ValueError("Lease length must be a positive integer.")
        self.vehicle_type = vehicle_type
        self.lease_length = lease_length

    def total_value(self):
        if self.vehicle_type == 'Car':
            multiplier = 1.2
        elif self.vehicle_type == 'Truck':
            multiplier = 1.7
        elif self.vehicle_type == 'Motorcycle':
            multiplier = 1.1
        else:
            raise ValueError("Invalid vehicle type.")
        return self.lease_length * multiplier

    def monthly_value(self):
        return self.total_value() / self.lease_length


# Test cases
bc = BuyContract(20000, 5000, 5, 'Customer')
assert abs(bc.total_value() - 18560) < 0.01
assert abs(bc.monthly_value(60) - 309.33) < 0.01

lc = LeaseContract('Car', 36)
assert abs(lc.total_value() - 43.2) < 0.01
assert abs(lc.monthly_value() - 1.18) < 0.01
```

