class AlbumService:
    def __init__(self):
        self.albums = []

    def add_record(self, title, artist, year, genre):
        if not all([isinstance(title, str), isinstance(artist, str), isinstance(year, int), isinstance(genre, str)]):
            raise ValueError("Invalid data types for title, artist, year, or genre")
        self.albums.append({"title": title, "artist": artist, "year": year, "genre": genre})
        return "Album added successfully"

    def get_all_albums(self):
        return self.albums

    def search_by_option(self, option, value):
        if option not in ["title", "artist", "year", "genre"]:
            raise ValueError("Invalid search option")
        return [album for album in self.albums if album[option] == value]


class MusicAlbumManager:
