def is_group_word(word):
    letter_groups = []
    current_group = [word[0]]

    for letter in word[1:]:
        if letter in current_group:
            return False
        if letter != current_group[0]:
            letter_groups.append(current_group)
            current_group = [letter]
        else:
            current_group.append(letter)

    letter_groups.append(current_group)

    for group in letter_groups:
        if len(set(group)) != 1:
            return False

    return True

