```python
from collections import deque

def isEscapePossible(blocked, source, target):
    blocked = set(map(tuple, blocked))

    def isValid(x, y):
        return 0 <= x < 10**6 and 0 <= y < 10**6 and (x, y) not in blocked

    def bfs(source, target):
        bfsQueue = deque([(0, source[0], source[1])])
        visited = set()
        while bfsQueue:
            dist, x, y = bfsQueue.popleft()
            if (x, y) == target or dist > 200:
                return True
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = x + dx, y + dy
                if isValid(nx, ny) and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    bfsQueue.append((dist + 1, nx, ny))
        return False

    return bfs(source, target) and bfs(target, source)
```

