```python
from flask import Flask, jsonify, request
from flask_jwt_extended import JWTManager, jwt_required, create_access_token, create_refresh_token, get_jwt_identity
from werkzeug.security import generate_password_hash, check_password_hash

app = Flask(__name__)
app.config['JWT_SECRET_KEY'] = 'super-secret'  # Change this!
jwt = JWTManager(app)

users = {}
tasks = {}

class UserModel:
    def __init__(self, email, password):
        self.email = email
        self.password = generate_password_hash(password)

    def check_password(self, password):
        return check_password_hash(self.password, password)

@app.route('/api/v2/register', methods=['POST'])
def register():
    email = request.json.get('email', None)
    password = request.json.get('password', None)
    if not email or not password:
        return jsonify({'msg': 'Missing email or password'}), 400
    if email in users:
        return jsonify({'msg': 'Email already registered'}), 400
    users[email] = UserModel(email, password)
    return jsonify({'msg': 'User registered successfully'}), 201

@app.route('/api/v2/login', methods=['POST'])
def login():
    email = request.json.get('email', None)
    password = request.json.get('password', None)
    if not email or not password:
        return jsonify({'msg': 'Missing email or password'}), 400
    user = users.get(email, None)
    if not user or not user.check_password(password):
        return jsonify({'msg': 'Bad email or password'}), 401
    access_token = create_access_token(identity=email)
    refresh_token = create_refresh_token(identity=email)
    return jsonify(access_token=access_token, refresh_token=refresh_token), 200

@app.route('/api/v2/refresh', methods=['POST'])
@jwt_required(refresh=True)
def refresh():
    identity = get_jwt_identity()
    access_token = create_access_token(identity=identity)
    return jsonify(access_token=access_token), 200

@app.route('/api/v2/identity', methods=['GET'])
@jwt_required()
def identity():
    identity = get_jwt_identity()
    return jsonify(identity=identity), 200

@app.route('/api/v2/tasks', methods=['POST'])
@jwt_required()
def create_task():
    identity = get_jwt_identity()
    task = request.json.get('task', None)
    if not task:
        return jsonify({'msg': 'Missing task'}), 400
    if identity not in tasks:
        tasks[identity] = []
    tasks[identity].append(task)
    return jsonify({'msg': 'Task created successfully'}), 201

@app.route('/api/v2/tasks', methods=['GET'])
@jwt_required()
def get_tasks():
    identity = get_jwt_identity()
    user_tasks = tasks.get(identity, [])
    return jsonify(tasks=user_tasks), 200

@app.route('/api/v2/tasks/<int:task_id>', methods=['PUT', 'DELETE'])
@jwt_required()
def modify_task(task_id):
    identity = get_jwt_identity()
    user_tasks = tasks.get(identity, [])
    if task_id >= len(user_tasks):
        return jsonify({'msg': 'Task not found'}), 404
    if request.method == 'PUT':
        new_task = request.json.get('task', None)
        if not new_task:
            return jsonify({'msg': 'Missing task'}), 400
        user_tasks[task_id] = new_task
        return jsonify({'msg': 'Task updated successfully'}), 200
    elif request.method == 'DELETE':
        del user_tasks[task_id]
        return jsonify({'msg': 'Task deleted successfully'}), 200

if __name__ == '__main__':
    app.run(debug=True)
