from flask import Flask, render_template, redirect, url_for
from flask_wtf import FlaskForm
from wtforms import StringField, SubmitField
from wtforms.validators import DataRequired

app = Flask(__name__)
app.config['SECRET_KEY'] = 'your-secret-key'

class BandForm(FlaskForm):
    band = StringField('Band Name', validators=[DataRequired()])
    submit = SubmitField('Submit')

@app.route('/', methods=['GET', 'POST'])
def index():
    form = BandForm()
    if form.validate_on_submit():
        if form.band.data.lower() == 'meshuggah':
            return redirect(url_for('band', message='You were right!'))
        else:
            return redirect(url_for('band', message='Try again!'))
    return render_template('index.html', form=form)

@app.route('/band')
def band():
    message = 'You were right!' if 'You were right!' in url_for('band', message='You were right!') else 'Try again!'
    return render_template('band.html', message=message)

if __name__ == '__main__':
    app.run(debug=True)
```

