```python
from flask import Flask, render_template, request, redirect, url_for
from flask_sqlalchemy import SQLAlchemy

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'postgresql://user:password@localhost/dbname'
db = SQLAlchemy(app)

class Mango(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    total_cost = db.Column(db.Float)
    quantity = db.Column(db.Integer)
    country_of_origin = db.Column(db.String(50))
    price_per_unit = db.Column(db.Float)
    image_url = db.Column(db.String(200))
    commodity_type = db.Column(db.String(50))
    fixed_overhead = db.Column(db.Float)
    variable_overhead = db.Column(db.Float)

@app.route('/')
def home():
    return render_template('home.html')

@app.route('/sell', methods=['GET', 'POST'])
def sell():
    if request.method == 'POST':
        mango = Mango(total_cost=request.form['total_cost'],
                      quantity=request.form['quantity'],
                      country_of_origin=request.form['country_of_origin'],
                      price_per_unit=request.form['price_per_unit'],
                      image_url=request.form['image_url'],
                      commodity_type=request.form['commodity_type'],
                      fixed_overhead=request.form['fixed_overhead'],
                      variable_overhead=request.form['variable_overhead'])
        db.session.add(mango)
        db.session.commit()
        return redirect(url_for('confirmation', id=mango.id))
    return render_template('sell.html')

@app.route('/confirmation/<int:id>')
def confirmation(id):
    mango = Mango.query.get(id)
    return render_template('confirmation.html', mango=mango)

@app.route('/list')
def list_mangos():
    mangos = Mango.query.all()
    return render_template('list.html', mangos=mangos)

@app.route('/error')
def error():
    return 1 / 0

if __name__ == '__main__':
    app.run(debug=True)
```

