```python
import torch
import torch.nn as nn
import torch.nn.functional as F

class GPP(nn.Module):
    def __init__(self, gpp_type, levels, pool_type):
        super(GPP, self).__init__()
        self.gpp_type = gpp_type
        self.levels = levels
        self.pool_type = pool_type

        if self.pool_type == 'max_pool':
            self.pool = F.max_pool2d
        elif self.pool_type == 'avg_pool':
            self.pool = F.avg_pool2d
        else:
            raise ValueError("Unknown pool_type. It should be 'max_pool' or 'avg_pool'")

    def forward(self, x, mask=None):
        if self.gpp_type == 'spp':
            return self._spatial_pyramid_pooling(x, mask)
        elif self.gpp_type == 'tpp':
            return self._temporal_pyramid_pooling(x, mask)
        elif self.gpp_type == 'gpp':
            return self._generic_pyramid_pooling(x, mask)
        else:
            raise ValueError("Unknown gpp_type. It should be 'spp', 'tpp', or 'gpp'")

    def _spatial_pyramid_pooling(self, x, mask=None):
        batch_size, channels, height, width = x.size()
        output_size = height // self.levels
        output = []
        for level in range(self.levels):
            kernel_size = height // (output_size * (level + 1))
            stride = height // (output_size * level) if level > 0 else None
            pooled = self.pool(x, kernel_size=kernel_size, stride=stride)
            output.append(pooled.view(batch_size, -1))
        return torch.cat(output, 1)

    def _temporal_pyramid_pooling(self, x, mask=None):
        batch_size, channels, frames = x.size()
        output_size = frames // self.levels
        output = []
        for level in range(self.levels):
            kernel_size = frames // (output_size * (level + 1))
            stride = frames // (output_size * level) if level > 0 else None
            pooled = self.pool(x, kernel_size=kernel_size, stride=stride)
            output.append(pooled.view(batch_size, -1))
        return torch.cat(output, 1)

    def _generic_pyramid_pooling(self, x, mask=None):
        batch_size, channels, height, width = x.size()
        output = []
        for level in self.levels[0]:
            kernel_size = height // level
            pooled = self.pool(x, kernel_size=kernel_size)
            output.append(pooled.view(batch_size, -1))
        for level in self.levels[1]:
            kernel_size = width // level
            pooled = self.pool(x, kernel_size=kernel_size)
            output.append(pooled.view(batch_size, -1))
        return torch.cat(output, 1)
