import abc
import numpy as np

class Layer(abc.ABC):
    @abc.abstractmethod
    def to_dict(self):
        pass

    @staticmethod
    @abc.abstractmethod
    def from_dict(dict_):
        pass

    @abc.abstractmethod
    def get_output_shape(self):
        pass

    @abc.abstractmethod
    def get_output_size(self):
        pass

class Input(Layer):
    def __init__(self, shape):
        self.shape = shape

    def to_dict(self):
        return {'shape': self.shape}

    @staticmethod
    def from_dict(dict_):
        if 'shape' not in dict_:
            raise ValueError('Missing shape parameter')
        return Input(dict_['shape'])

    def get_output_shape(self):
        return self.shape

    def get_output_size(self):
        return np.prod(self.shape)

class Convolution(Layer):
    def __init__(self, input_shape, kernel_size, stride):
        self.input_shape = input_shape
        self.kernel_size = kernel_size
        self.stride = stride

    def to_dict(self):
        return {'input_shape': self.input_shape, 'kernel_size': self.kernel_size, 'stride': self.stride}

    @staticmethod
    def from_dict(dict_):
        if 'input_shape' not in dict_ or 'kernel_size' not in dict_ or 'stride' not in dict_:
            raise ValueError('Missing parameters')
        return Convolution(dict_['input_shape'], dict_['kernel_size'], dict_['stride'])

    def get_output_shape(self):
        return tuple((np.array(self.input_shape) - np.array(self.kernel_size)) // np.array(self.stride) + 1)

    def get_output_size(self):
        return np.prod(self.get_output_shape())

class Pooling(Layer):
    def __init__(self, input_shape, pool_size, stride):
        self.input_shape = input_shape
        self.pool_size = pool_size
        self.stride = stride

    def to_dict(self):
        return {'input_shape': self.input_shape, 'pool_size': self.pool_size, 'stride': self.stride}

    @staticmethod
    def from_dict(dict_):
        if 'input_shape' not in dict_ or 'pool_size' not in dict_ or 'stride' not in dict_:
            raise ValueError('Missing parameters')
        return Pooling(dict_['input_shape'], dict_['pool_size'], dict_['stride'])

    def get_output_shape(self):
        return tuple((np.array(self.input_shape) - np.array(self.pool_size)) // np.array(self.stride) + 1)

    def get_output_size(self):
        return np.prod(self.get_output_shape())

class FullConnection(Layer):
    def __init__(self, input_size, output_size):
