import wikipedia
import socket

class TCPclient:
    def __init__(self, host, port):
        self.host = host
        self.port = port
        self.client = socket.socket(socket.AF_INET, socket.SOCK_STREAM)

    def connect(self):
        self.client.connect((self.host, self.port))

    def send(self, data):
        self.client.send(data.encode())

    def receive(self):
        return self.client.recv(1024).decode()

    def close(self):
        self.client.close()

def isValid(text):
    return "Wikipedia" in text

def handle(search_term):
    try:
        summary = wikipedia.summary(search_term, sentences=3)
        return summary
    except wikipedia.exceptions.PageError:
        return "No Wikipedia page found for the term: " + search_term
    except wikipedia.exceptions.DisambiguationError:
        return "The search term is ambiguous. Please provide more details."

def main():
    client = TCPclient('localhost', 8080)
    client.connect()

    while True:
        data = client.receive()
        if isValid(data):
            search_term = input("Please enter your search term: ")
            while search_term.lower() == "wikipedia":
                search_term = input("Please enter a different term. 'Wikipedia' is not a valid search term: ")
            summary = handle(search_term)
            client.send(summary)

if __name__ == "__main__":
    main()
