    if not os.path.exists(file_path):
        errors.append(f"File {file_path} does not exist.")
        return errors, warnings

    if not file_path.endswith('.lol'):
        errors.append(f"File {file_path} is not a .lol file.")
        return errors, warnings

    try:
        with open(file_path, 'r') as file:
            lol_file = l20n.Parser().parse(file.read())
    except Exception as e:
        errors.append(f"Error parsing file {file_path}: {str(e)}")
        return errors, warnings

    for entity in lol_file.entities:
        if entity.id in identifiers:
            warnings.append(f"Duplicate identifier {entity.id} found.")
        else:
            identifiers[entity.id] = True

    for macro in lol_file.macros:
        if macro.id in identifiers:
            warnings.append(f"Duplicate identifier {macro.id} found.")
        else:
            identifiers[macro.id] = True

    return errors, warnings
```

