```python
import glfw
from Matrix import Matrix

class WASDController:
    def __init__(self, speed=1.0, sensitivity=0.001, invert_y=False, lock_mouse=True):
        self.speed = speed
        self.sensitivity = sensitivity
        self.invert_y = invert_y
        self.lock_mouse = lock_mouse
        self.position = [0, 0, 0]
        self.yaw = -90
        self.pitch = 0
        self.last_x, self.last_y = glfw.get_cursor_pos(window)
        self.first_mouse = True
        glfw.set_input_mode(window, glfw.CURSOR, glfw.CURSOR_DISABLED if lock_mouse else glfw.CURSOR_NORMAL)

    def update(self, window, delta_time):
        self.handle_keyboard(window, delta_time)
        self.handle_mouse(window, delta_time)

    def handle_keyboard(self, window, delta_time):
        camera_speed = self.speed * delta_time
        if glfw.get_key(window, glfw.KEY_W) == glfw.PRESS:
            self.position[2] -= camera_speed
        if glfw.get_key(window, glfw.KEY_S) == glfw.PRESS:
            self.position[2] += camera_speed
        if glfw.get_key(window, glfw.KEY_A) == glfw.PRESS:
            self.position[0] -= camera_speed
        if glfw.get_key(window, glfw.KEY_D) == glfw.PRESS:
            self.position[0] += camera_speed

    def handle_mouse(self, window, delta_time):
        xpos, ypos = glfw.get_cursor_pos(window)
        if self.first_mouse:
            self.last_x, self.last_y = xpos, ypos
            self.first_mouse = False
        x_offset = xpos - self.last_x
        y_offset = ypos - self.last_y
        self.last_x, self.last_y = xpos, ypos
        x_offset *= self.sensitivity
        y_offset *= self.sensitivity
        self.yaw += x_offset
        self.pitch += y_offset if not self.invert_y else -y_offset
        if self.pitch > 89:
            self.pitch = 89
        if self.pitch < -89:
            self.pitch = -89

    def get_position(self):
        return self.position

    def get_view_direction(self):
        front_x = cos(radians(self.yaw)) * cos(radians(self.pitch))
        front_y = sin(radians(self.pitch))
        front_z = sin(radians(self.yaw)) * cos(radians(self.pitch))
        return [front_x, front_y, front_z]

    def get_transformation_matrix(self):
        return Matrix.look_at(self.position, self.get_view_direction(), [0, 1, 0])

    def handle_mouse_button(self, window, button, action, mods):
        if button == glfw.MOUSE_BUTTON_LEFT and action == glfw.PRESS:
            self.lock_mouse = not self.lock_mouse
            glfw.set_input_mode(window, glfw.CURSOR, glfw.CURSOR_DISABLED if self.lock_mouse else glfw.CURSOR_NORMAL)

    def handle_key(self, window, key, scancode, action, mods):
        if key == glfw.KEY_ESCAPE and action == glfw.PRESS:
            self.lock_mouse = False
            glfw.set_input_mode(window, glfw.CURSOR, glfw.CURSOR_NORMAL)
