        raise ValueError("Invalid timezone")
    now = datetime.datetime.now(pytz.timezone(timezone_str))
    return now.strftime('%Y-%m-%d %H:%M:%S')

def within_time_interval(start_time, end_time, timezone_str):
    if timezone_str not in all_timezones:
        raise ValueError("Invalid timezone")
    if not isinstance(start_time, datetime.timedelta) or not isinstance(end_time, datetime.timedelta):
        raise ValueError("Start time and end time must be of type datetime.timedelta")
    now = datetime.datetime.now(pytz.timezone(timezone_str))
    now_time = datetime.timedelta(hours=now.hour, minutes=now.minute, seconds=now.second)
    if start_time < end_time:
        return [start_time <= now_time <= end_time, now_time > end_time]
    else: # start_time > end_time
        return [now_time >= start_time or now_time <= end_time, now_time < end_time]
