        inputs = tf.keras.Input(shape=input_shape)

        # First convolutional layer
        x = layers.Conv2D(64, kernel_size=7, strides=2, padding='same', data_format=self.data_format)(inputs)
        x = layers.BatchNormalization()(x)
        x = layers.Activation('relu')(x)
        x = layers.MaxPool2D(pool_size=3, strides=2, padding='same', data_format=self.data_format)(x)

        # Residual blocks
        if self.num_layers == 26:
            for _ in range(3):
