class Quixo:
    def __init__(self):
        self.board = [[' ' for _ in range(5)] for _ in range(5)]
        self.turn = 'O'

    def print_board(self):
        for row in self.board:
            print(' '.join(row))
        print()

    def make_move(self, piece, direction):
        dx, dy = {'up': (-1, 0), 'down': (1, 0), 'left': (0, -1), 'right': (0, 1)}[direction]
        x, y = divmod(piece - 1, 5)
        if self.board[x][y] != self.turn:
            raise ValueError('Invalid move')
        while 0 <= x + dx < 5 and 0 <= y + dy < 5 and self.board[x + dx][y + dy] == ' ':
            x, y = x + dx, y + dy
        self.board[x][y] = self.turn
        self.board[piece // 5][piece % 5] = ' '

    def check_win(self):
        for i in range(5):
            if all(self.board[i][j] == self.turn for j in range(5)) or all(self.board[j][i] == self.turn for j in range(5)):
                return True
        if all(self.board[i][i] == self.turn for i in range(5)) or all(self.board[i][4 - i] == self.turn for i in range(5)):
            return True
        return False

    def play(self):
        self.print_board()
        while True:
            try:
                piece = int(input(f'Player {self.turn}, enter the piece to move (1-25): '))
                direction = input(f'Enter the direction to move (up, down, left, right): ')
                self.make_move(piece, direction)
                self.print_board()
                if self.check_win():
                    print(f'Player {self.turn} wins!')
                    break
                self.turn = 'X' if self.turn == 'O' else 'O'
            except ValueError as e:
                print(e)

if __name__ == '__main__':
    Quixo().play()
