from flask import Flask, jsonify, request
from flask_marshmallow import Marshmallow
from marshmallow import ValidationError
from flask_sqlalchemy import SQLAlchemy

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:////tmp/test.db'
db = SQLAlchemy(app)
ma = Marshmallow(app)

class Product(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(80), nullable=False)
    quantity = db.Column(db.Integer, nullable=False)

class ProductSchema(ma.SQLAlchemyAutoSchema):
    class Meta:
        model = Product

product_schema = ProductSchema()
products_schema = ProductSchema(many=True)

@app.route('/product', methods=['POST'])
def add_product():
    try:
        new_product = product_schema.load(request.json)
    except ValidationError as err:
        return jsonify(err.messages), 400

    db.session.add(new_product)
    db.session.commit()
    return product_schema.jsonify(new_product), 201

@app.route('/product', methods=['GET'])
def get_products():
    all_products = Product.query.all()
    return products_schema.jsonify(all_products)

@app.route('/product/<id>', methods=['GET'])
def get_product(id):
    product = Product.query.get(id)
    if product is None:
        return jsonify({'message': 'Product not found'}), 404
    return product_schema.jsonify(product)

@app.route('/product/<id>', methods=['PUT'])
def update_product(id):
    product = Product.query.get(id)
    if product is None:
        return jsonify({'message': 'Product not found'}), 404

    try:
        product = product_schema.load(request.json, instance=product)
    except ValidationError as err:
        return jsonify(err.messages), 400

    db.session.commit()
    return product_schema.jsonify(product)

@app.route('/product/<id>', methods=['DELETE'])
def delete_product(id):
    product = Product.query.get(id)
    if product is None:
        return jsonify({'message': 'Product not found'}), 404

    db.session.delete(product)
    db.session.commit()

    return jsonify({'message': 'Product deleted'}), 200

if __name__ == '__main__':
    db.create_all()
    app.run(debug=True)
```

This code creates a simple REST API for managing a product inventory. It uses Flask-SQLAlchemy for database operations and Flask-Marshmallow for serialization and deserialization of product data.

The `Product` model represents a product in the inventory with `id`, `name`, and `quantity` attributes. The `ProductSchema` class is used to serialize and deserialize instances of the `Product` model.

The `add_product`, `get_products`, `get_product`, `update_product`, and `delete_product` functions implement the API endpoints for creating, retrieving, updating, and deleting products.

The `ValidationError` exception is used to handle invalid input data. If input data is invalid, the function returns a 400 Bad Request response with a list of error messages.

The `if __name__ == '__main__':` block creates the database tables and starts the Flask development server if the script is run directly.

Please note that this is a simple implementation and does not include any authentication or authorization for the API endpoints. In a production environment, you would want to add these features to ensure that only authorized users can access the API.

