```python
from cryptography.fernet import Fernet
from datetime import datetime, date
import abc

class Secure(abc.ABC):
    def __init__(self, value, encryption_level, access_level):
        self.value = value
        self.encryption_level = encryption_level
        self.access_level = access_level
        self.key = Fernet.generate_key()
        self.cipher_suite = Fernet(self.key)

    def encrypt(self):
        cipher_text = self.cipher_suite.encrypt(self.value.encode())
        return cipher_text

    def decrypt(self):
        if self.access_level >= self.encryption_level:
            plain_text = self.cipher_suite.decrypt(self.value).decode()
            return plain_text
        else:
            raise Exception("Unauthorized access")

    @abc.abstractmethod
    def get_typed_value(self):
        pass

class SecureString(Secure, str):
    def __init__(self, value, encryption_level, access_level):
        super().__init__(value, encryption_level, access_level)
        self.value = self.encrypt()

    def get_typed_value(self):
        return str(self.decrypt())

class SecureDecimal(Secure, float):
    def __init__(self, value, encryption_level, access_level):
        super().__init__(value, encryption_level, access_level)
        self.value = self.encrypt()

    def get_typed_value(self):
        return float(self.decrypt())

class SecureDate(Secure, date):
    def __init__(self, value, encryption_level, access_level):
        super().__init__(value, encryption_level, access_level)
        self.value = self.encrypt()

    def get_typed_value(self):
        return datetime.strptime(self.decrypt(), "%Y-%m-%d").date()

class SecureDateTime(Secure, datetime):
    def __init__(self, value, encryption_level, access_level):
        super().__init__(value, encryption_level, access_level)
        self.value = self.encrypt()

    def get_typed_value(self):
        return datetime.strptime(self.decrypt(), "%Y-%m-%d %H:%M:%S")

class SecureIncompleteDate(Secure, date):
    def __init__(self, value, encryption_level, access_level):
        super().__init__(value, encryption_level, access_level)
        self.value = self.encrypt()

    def get_typed_value(self):
        return datetime.strptime(self.decrypt(), "%Y-%m").date()
