from scipy.stats import gaussian_kde
import numpy as np
import os

# Define the models, scenarios, GWLs, and variables to be used
models = ['model1', 'model2']
scenarios = ['scenario1', 'scenario2']
GWLs = ['GWL1', 'GWL2']
variables = ['temperature', 'skin_temperature', 'precipitation', 'wind_speed', 'soil_moisture']
regions = ['boreal', 'euusarc', 'afrea']
seasons = ['spring', 'summer', 'autumn', 'winter']

# Define the data directory
data_dir = 'path_to_data_directory'

# Define the output directory
output_dir = 'path_to_output_directory'

# Load the data for the specified variables and scenarios
def getGWLdata(model, scenario, GWL, variable):
    filename = f'{model}_{scenario}_{GWL}_{variable}.csv'
    filepath = os.path.join(data_dir, filename)
    try:
        data = pd.read_csv(filepath)
    except FileNotFoundError:
        print(f'File not found: {filepath}')
        return None
    return data

# Group the data by season
def groupManybySeason(data, seasons):
    return {season: data[data['season'] == season] for season in seasons}

# Calculate the PDF for each variable, region, and season
def calculatePDF(data, variable):
    return gaussian_kde(data[variable])

# Plot the PDFs
def plotPDFs(pdfs, variable, region, season, output_dir):
    fig, ax = plt.subplots()
    for model in pdfs:
        for scenario in pdfs[model]:
            x = np.linspace(min(pdfs[model][scenario].dataset), max(pdfs[model][scenario].dataset), 100)
            ax.plot(x, pdfs[model][scenario](x), label=f'{model}_{scenario}')
    ax.set_title(f'{variable} in {region} during {season}')
    ax.set_xlabel(variable)
    ax.set_ylabel('PDF')
    ax.legend()
    output_path = os.path.join(output_dir, f'{variable}_{region}_{season}.png')
    plt.savefig(output_path)
    plt.close()

# Main function
