    pdfs = {}
    for model in models:
        pdfs[model] = {}
        for scenario in scenarios:
            pdfs[model][scenario] = {}
            for GWL in GWLs:
                pdfs[model][scenario][GWL] = {}
                for variable in variables:
                    pdfs[model][scenario][GWL][variable] = {}
