# Define the source and destination directories
src_dir = 'source_directory'
ead_dir = 'ead_directory'
callno_dir = 'callno_directory'
no_dir = 'no_directory'

# Define the namespaces
ns = {'ead': 'urn:isbn:1-931666-22-9', 'marc': 'http://www.loc.gov/MARC21/slim'}

# Check if the source directories exist
if not os.path.exists(src_dir):
    print(f"Source directory {src_dir} does not exist.")
    exit(1)

if not os.path.exists(ead_dir):
    os.makedirs(ead_dir)

if not os.path.exists(callno_dir):
    os.makedirs(callno_dir)

if not os.path.exists(no_dir):
    os.makedirs(no_dir)

# Parse the EAD files to create a list of call numbers and collection IDs
ead_list = []
for filename in os.listdir(ead_dir):
    if filename.endswith('.xml'):
        tree = ET.parse(os.path.join(ead_dir, filename))
        root = tree.getroot()
        callno = root.find('.//ead:archdesc/ead:did/ead:unitid', ns).text
        collection_id = root.find('.//ead:eadid', ns).text
        ead_list.append((callno, collection_id))

# Parse the MARC records and copy them into the appropriate directory
for filename in os.listdir(src_dir):
    if filename.endswith('.xml'):
        try:
            tree = ET.parse(os.path.join(src_dir, filename))
            root = tree.getroot()
            ead_link = root.find('.//marc:datafield[@tag="856"]/marc:subfield[@code="u"]', ns)
            callno = root.find('.//marc:datafield[@tag="852"]/marc:subfield[@code="h"]', ns)
            if ead_link is not None:
                shutil.copy(os.path.join(src_dir, filename), ead_dir)
            elif callno is not None:
                shutil.copy(os.path.join(src_dir, filename), callno_dir)
            else:
                shutil.copy(os.path.join(src_dir, filename), no_dir)
        except Exception as e:
            print(f"Error processing file {filename}: {str(e)}")
